let fillSnap={op:"stat",have:0,total:MEDIA_FILES.length,state:"idle",fail:0,more:false,step:"stop",reason:"",shell:false,phase:""};
function fillSend(msg,source){
  fillSeq+=1;msg=Object.assign({},msg,{seq:fillSeq});fillSnap=msg;
  const data={t:"fill",...msg},seen=new Set();
  const post=c=>{if(!c||typeof c.postMessage!="function")return;const id=c.id||"";if(id&&seen.has(id))return;if(id)seen.add(id);try{c.postMessage(data)}catch(err){}};
  post(source);
  return self.clients.matchAll({includeUncontrolled:true}).then(cs=>cs.forEach(post)).catch(()=>{});
}
function fillEnqueue(fn){const p=fillChain.then(fn,fn);fillChain=p.then(()=>{},()=>{});return p}
function fillQuota(e){return !!(e&&(e.name==="QuotaExceededError"||/quota/i.test(String(e.message||e))))}
async function cacheOne(cache,key,req){
  let last=0;
  for(let a=0;a<2;a++){
    const ctrl=typeof AbortController=="function"?new AbortController():null;
    const timer=ctrl?setTimeout(()=>ctrl.abort(),60000):0;
    try{
      const r=await fetch(req,{cache:"no-store",signal:ctrl?ctrl.signal:undefined});
      last=r.status;
      if(r.ok){await cache.put(key,r);return 200}
      try{r.body&&r.body.cancel()}catch(err){}
      if(r.status<500)return r.status;
    }catch(e){
      if(fillQuota(e))throw e;
      if(a===1)throw e;
    }finally{if(timer)clearTimeout(timer)}
  }
  return last||500;
}
async function ensureShell(){
  if(shellReady)return "";
  const c=await caches.open(SHELL);
  let n=0;
  for(const f of SHELL_FILES){
    if(shellMiss.has(f)||await c.match(f))continue;
    if(n>=FILL_BATCH)return "more";
    n++;
    try{
      const st=await cacheOne(c,f,f);
      if(st!==200)shellMiss.add(f);
    }catch(e){
      if(fillQuota(e))return "quota";
      return "offline";
    }
  }
  shellReady=true;return "";
}
async function fillScan(){
  const m=await caches.open(MEDIA);const miss=[];let have=0;
  for(const f of MEDIA_FILES){if(await m.match(mk(f)))have++;else miss.push(f)}
  fillTodo=miss;fillIdx=0;fillHave=have;fillFailed=new Set();
}
function fillPending(){let n=0;for(let i=fillIdx;i<fillTodo.length;i++)if(!fillFailed.has(fillTodo[i]))n++;return n}
function fillFailN(){return fillFailed.size+shellMiss.size}
async function fillStat(source){
  // Don't rebuild the queue mid-download; opening 设置 only asks for the latest counts.
  if(fillSnap.state==="run"&&fillSnap.op==="fill"&&fillTodo&&(fillPending()>0||!shellReady)){await fillSend(Object.assign({},fillSnap,{op:"stat"}),source);return}
  const prev=fillSnap.state,prevReason=fillSnap.reason||"";
  await fillScan();
  const more=fillTodo.length>0,shellBad=shellMiss.size>0;
  const state=!more&&!shellBad?"done":prev==="pause"?"pause":(prev==="fail"||shellBad)?"fail":"idle";
  const reason=state==="pause"?"offline":state==="fail"&&prevReason==="quota"?"quota":"";
  const fail=state==="fail"?Math.max(fillFailN(),fillTodo.length):0;
  await fillSend({op:"stat",have:fillHave,total:MEDIA_FILES.length,state,fail,more:more||shellBad,step:"stop",reason,shell:shellReady&&!shellBad,phase:""},source);
}
async function fillBatch(retry,source){
  try{
    if(retry){shellReady=false;shellMiss=new Set();fillTodo=null;fillFailed=new Set()}
    await fillSend({op:"fill",have:fillHave,total:MEDIA_FILES.length,state:"run",fail:fillFailN(),more:true,step:"work",reason:"",shell:shellReady,phase:"scan"},source);
    if(!fillTodo)await fillScan();
    const shellErr=await ensureShell();
    if(shellErr==="more"){await fillSend({op:"fill",have:fillHave,total:MEDIA_FILES.length,state:"run",fail:fillFailN(),more:true,step:"next",reason:"",shell:false,phase:"shell"},source);return}
    if(shellErr==="offline"||shellErr==="quota"){
      await fillSend({op:"fill",have:fillHave,total:MEDIA_FILES.length,state:shellErr==="offline"?"pause":"fail",fail:fillFailN(),more:shellErr==="offline",step:"stop",reason:shellErr,shell:false,phase:"shell"},source);return}
    const m=await caches.open(MEDIA);
    let n=0,net=false,quota=false;
    while(fillIdx<fillTodo.length&&n<FILL_BATCH){
      const f=fillTodo[fillIdx];
      if(fillFailed.has(f)){fillIdx++;continue}
      if(await m.match(mk(f))){fillHave++;fillIdx++;continue}
      n++;
      try{
        const st=await cacheOne(m,mk(f),mk(f));
        if(st===200){fillHave++;fillIdx++}
        else{fillFailed.add(f);fillIdx++}
      }catch(e){
        if(fillQuota(e)){quota=true;break}
        net=true;break;
      }
    }
    const pending=fillPending();
    let state,more,step,reason="";
    if(quota){state="fail";more=false;step="stop";reason="quota"}
    else if(net){state="pause";more=true;step="stop";reason="offline"}
    else if(pending>0){state="run";more=true;step="next";reason=""}
    else if(fillFailN()){state="fail";more=false;step="stop";reason:""}
    else{state="done";more=false;step="stop";reason=""}
    await fillSend({op:"fill",have:fillHave,total:MEDIA_FILES.length,state,fail:fillFailN(),more,step,reason,shell:true,phase:"media"},source);
  }catch(e){
    await fillSend({op:"fill",have:fillHave,total:MEDIA_FILES.length,state:"pause",fail:fillFailN(),more:true,step:"stop",reason:"offline",shell:shellReady,phase:"media"},source);
  }
}
self.addEventListener("message",e=>{const d=e.data||{};
  if(d.t=="skip")self.skipWaiting();
  if(d.t=="ver")e.source&&e.source.postMessage({t:"ver",v:V,media:MEDIA_FILES.length,shell:SHELL_FILES.length});
  if(d.t=="stat"||d.t=="fill"){
    const source=e.source||null,retry=!!d.retry,kind=d.t;
    const p=fillEnqueue(()=>kind=="stat"?fillStat(source):fillBatch(retry,source)).catch(()=>{});
    e.waitUntil(p);
  }
});
