async function rangeResp(resp,range){const b=await resp.blob();const m=/bytes=(\d*)-(\d*)/.exec(range)||[];let s=+m[1]||0,end=m[2]?+m[2]:b.size-1;end=Math.min(end,b.size-1);
  return new Response(b.slice(s,end+1),{status:206,headers:{"Content-Type":resp.headers.get("Content-Type")||"audio/mpeg","Content-Range":`bytes ${s}-${end}/${b.size}`,"Content-Length":String(end-s+1),"Accept-Ranges":"bytes"}})}
self.addEventListener("fetch",e=>{const req=e.request,u=new URL(req.url);if(req.method!="GET"||u.origin!=location.origin)return;
  const rel=u.pathname.slice(new URL(self.registration.scope).pathname.length);
  if(rel=="sw.js")return;
  if(isMedia(rel)){e.respondWith((async()=>{try{const m=await caches.open(MEDIA);const key=mk(rel);let hit=await m.match(key);
    if(!hit){let r;try{r=await fetch(key,{cache:"no-store"})}catch(err){return await fetch(req)}
      if(!r.ok){try{return await fetch(req)}catch(err){return r}}
      try{await m.put(key,r.clone())}catch(err){}
      hit=r}
    const range=req.headers.get("range");return range?rangeResp(hit.clone(),range):hit}catch(err){try{return await fetch(req)}catch(e2){return Response.error()}}})());return}
  // network-first for html/js/css/json (fresh when online, cached when offline).
  // meta.json and content/check.enc must not be answered with index.html: that
  // body fails AES-GCM and the lock screen used to say 密码不对.
  e.respondWith((async()=>{const c=await caches.open(SHELL);const key=req.mode=="navigate"?"index.html":(rel||"index.html");
    const gate=key=="meta.json"||/(^|\/)check\.enc$/.test(key);
    try{const r=await fetch(req.mode=="navigate"?"index.html":req,{cache:"no-store"});
      if(r.ok){const ct=(r.headers.get("content-type")||"").toLowerCase();if(!(gate&&ct.includes("text/html")))c.put(key,r.clone())}
      return r}
    catch(err){const hit=await c.match(key,{ignoreSearch:true});if(hit)return hit;if(gate)return Response.error();return (await c.match("index.html"))||Response.error()}})())});
